143	function pngChunk(type, data) {
144	  const typeBuf = Buffer.from(type, 'ascii')
145	  const lenBuf = Buffer.alloc(4)
146	  lenBuf.writeUInt32BE(data.length, 0)
147	  const crcBuf = Buffer.alloc(4)
148	  crcBuf.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])), 0)
149	  return Buffer.concat([lenBuf, typeBuf, data, crcBuf])
150	}
