152	/** width x height 8비트 RGB(colorType=2) PNG 를 순수 zlib 으로 조립한다. colorFn(x,y) -> [r,g,b]. */
153	function encodePng(width, height, colorFn) {
154	  const rowBytes = width * 3
155	  const raw = Buffer.alloc((rowBytes + 1) * height)
156	  for (let y = 0; y < height; y++) {
157	    const rowStart = y * (rowBytes + 1)
158	    raw[rowStart] = 0 // 필터 없음
159	    for (let x = 0; x < width; x++) {
160	      const [r, g, b] = colorFn(x, y)
161	      const off = rowStart + 1 + x * 3
162	      raw[off] = r & 0xff
163	      raw[off + 1] = g & 0xff
164	      raw[off + 2] = b & 0xff
165	    }
166	  }
167	  const compressed = zlib.deflateSync(raw)
168	  const ihdr = Buffer.alloc(13)
169	  ihdr.writeUInt32BE(width, 0)
170	  ihdr.writeUInt32BE(height, 4)
171	  ihdr[8] = 8  // bit depth
172	  ihdr[9] = 2  // color type: truecolor RGB
173	  ihdr[10] = 0 // compression method
174	  ihdr[11] = 0 // filter method
175	  ihdr[12] = 0 // interlace method
176	  return Buffer.concat([
177	    PNG_SIGNATURE,
178	    pngChunk('IHDR', ihdr),
179	    pngChunk('IDAT', compressed),
180	    pngChunk('IEND', Buffer.alloc(0)),
181	  ])
182	}
