244	function parseMultipart(bodyBuf, boundary) {
245	  const boundaryBuf = Buffer.from(`--${boundary}`)
246	  const crlfcrlf = Buffer.from('\r\n\r\n')
247	  const parts = []
248	  let idx = bodyBuf.indexOf(boundaryBuf)
249	  while (idx !== -1) {
250	    const nextIdx = bodyBuf.indexOf(boundaryBuf, idx + boundaryBuf.length)
251	    if (nextIdx === -1) break
252	    let partStart = idx + boundaryBuf.length
253	    if (bodyBuf[partStart] === 0x0d && bodyBuf[partStart + 1] === 0x0a) partStart += 2
254	    let partEnd = nextIdx
255	    if (bodyBuf[partEnd - 2] === 0x0d && bodyBuf[partEnd - 1] === 0x0a) partEnd -= 2
256	    if (partEnd > partStart) parts.push(bodyBuf.subarray(partStart, partEnd))
257	    idx = nextIdx
258	  }
259	  const result = { fields: {}, files: {} }
260	  for (const part of parts) {
261	    const headerEnd = part.indexOf(crlfcrlf)
262	    if (headerEnd === -1) continue
263	    const headerStr = part.subarray(0, headerEnd).toString('utf8')
264	    const data = part.subarray(headerEnd + 4)
265	    const nameMatch = /name="([^"]*)"/.exec(headerStr)
266	    const filenameMatch = /filename="([^"]*)"/.exec(headerStr)
267	    const ctMatch = /Content-Type:\s*([^\r\n]+)/i.exec(headerStr)
268	    const name = nameMatch ? nameMatch[1] : ''
269	    if (!name) continue
270	    if (filenameMatch) {
271	      result.files[name] = {
272	        filename: filenameMatch[1],
273	        contentType: ctMatch ? ctMatch[1].trim() : 'application/octet-stream',
274	        data,
275	      }
276	    } else {
277	      result.fields[name] = data.toString('utf8')
278	    }
279	  }
280	  return result
281	}
