26	export async function pollUntil(fn, { timeoutMs = 10_000, intervalMs = 300, label = 'condition' } = {}) {
27	  const start = Date.now()
28	  let last
29	  let lastErr
30	  while (Date.now() - start < timeoutMs) {
31	    try {
32	      last = await fn()
33	      lastErr = null
34	      if (last) return last
35	    } catch (err) {
36	      lastErr = err
37	    }
38	    await sleep(intervalMs)
39	  }
40	  const suffix = lastErr ? ` (마지막 오류: ${lastErr.message})` : ''
41	  throw new Error(`timeout(${timeoutMs}ms) waiting for ${label}${suffix}`)
42	}
