44	// ── CDP 세션 ────────────────────────────────────────────────────────────
45	
46	/**
47	 * 한 CDP 타깃(페이지·브라우저)에 대한 WebSocket 세션.
48	 *
49	 * `events` 는 CDP 이벤트(msg.method) 구독자 목록이다. Electron 의 `webContents.debugger`
50	 * 시그니처(event, method, params, sessionId)로 호출하므로, 디버거를 흉내내는 하네스가
51	 * 그대로 쓸 수 있다(verify-agent-safety 의 파일 선택창 가로채기 검증이 이 경로를 쓴다).
52	 */
53	export class CDPSession {
54	  constructor(wsUrl, label) {
55	    this.wsUrl = wsUrl
56	    this.label = label
57	    this.ws = null
58	    this._id = 0
59	    this.pending = new Map()
60	    this.events = []
61	  }
62	
63	  async connect(timeoutMs = 10_000) {
64	    this.ws = new WebSocket(this.wsUrl)
65	    await withTimeout(new Promise((resolve, reject) => {
66	      this.ws.addEventListener('open', () => resolve())
67	      this.ws.addEventListener('error', (e) => reject(new Error(`ws error: ${e?.message ?? 'unknown'}`)))
68	    }), timeoutMs, `CDP ws connect (${this.label})`)
69	    this.ws.addEventListener('message', (ev) => this._onMessage(ev))
70	    this.ws.addEventListener('close', () => {
71	      for (const [, p] of this.pending) p.reject(new Error('ws closed before response'))
72	      this.pending.clear()
73	    })
74	  }
75	
76	  _onMessage(ev) {
77	    let msg
78	    try { msg = JSON.parse(ev.data) } catch { return }
79	    if (typeof msg.id === 'number' && this.pending.has(msg.id)) {
80	      const { resolve, reject } = this.pending.get(msg.id)
81	      this.pending.delete(msg.id)
82	      if (msg.error) reject(new Error(`CDP error [${msg.error.code}]: ${msg.error.message}`))
83	      else resolve(msg.result)
84	      return
85	    }
86	    if (typeof msg.method === 'string' && this.events.length) {
87	      for (const fn of this.events) {
88	        try { fn({}, msg.method, msg.params ?? {}, msg.sessionId) } catch { /* 구독자 예외는 세션을 죽이지 않는다 */ }
89	      }
90	    }
91	  }
92	
93	  send(method, params = {}, timeoutMs = 15_000) {
94	    if (!this.ws || this.ws.readyState !== 1 /* OPEN */) {
95	      return Promise.reject(new Error(`CDP session not open (${this.label}) — method=${method}`))
96	    }
97	    const id = (this._id += 1)
98	    const p = new Promise((resolve, reject) => {
99	      this.pending.set(id, { resolve, reject })
100	    })
101	    this.ws.send(JSON.stringify({ id, method, params }))
102	    // 타임아웃 시 pending 엔트리를 반드시 지운다 — 무응답 커맨드가 맵에 영구 잔류하면
103	    // 나중에 도착한 응답이 엉뚱한 대기자를 깨우거나, close 시 대량 reject 를 낳는다.
104	    return withTimeout(p, timeoutMs, `CDP ${method} (${this.label})`).catch((err) => {
105	      this.pending.delete(id)
106	      throw err
107	    })
108	  }
109	
110	  close() {
111	    try { this.ws?.close() } catch { /* ignore */ }
112	  }
113	}
114	
115	export async function connectSession(target, label) {
116	  const session = new CDPSession(target.webSocketDebuggerUrl, label ?? target.id)
117	  await session.connect()
118	  return session
119	}
