    const cur = wfMap().get(workflowId)
    if (!cur || cur.stage !== 'review' || cur.caption) return
    if (failure) {
      cur.captionError = `캡션을 만들지 못했습니다: ${failure} — 캡션을 직접 입력한 뒤 승인해 주세요.`
